  `token_type` enum('access','refresh') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_jti_type` (`jti`,`token_type`),
  KEY `created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- user_activity_logs
CREATE TABLE `user_activity_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `activity_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `title` enum('success','warning','info','danger') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id_fk3` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- metadata_versions
CREATE TABLE `metadata_versions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `table_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `version` int unsigned NOT NULL,
  `definition` json NOT NULL,
  `changes` json DEFAULT NULL,
  `changed_by` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metadata_versions_table_version` (`table_name`,`version`),
  CONSTRAINT `chk_metadata_versions_table` CHECK (regexp_like(`table_name`,_utf8mb4'^[A-Za-z_][A-Za-z0-9_]*$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- metadata_uploads
CREATE TABLE `metadata_uploads` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `table_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `column_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `record_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(768) COLLATE utf8mb4_general_ci NOT NULL,
  `public_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `mimetype` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `size_bytes` bigint unsigned DEFAULT NULL,
  `status` enum('PENDING','ATTACHED','REMOVED','DELETED') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING',
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `last_error` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uploaded_by` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_metadata_uploads_url` (`url`),
  KEY `idx_metadata_uploads_record` (`table_name`,`record_id`),
  KEY `idx_metadata_uploads_status` (`status`,`createdAt`),
  CONSTRAINT `chk_metadata_uploads_column` CHECK (regexp_like(`column_name`,_utf8mb4'^[A-Za-z_][A-Za-z0-9_]*$')),
  CONSTRAINT `chk_metadata_uploads_table` CHECK (regexp_like(`table_name`,_utf8mb4'^[A-Za-z_][A-Za-z0-9_]*$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- database_backups
CREATE TABLE `database_backups` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `file_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `destination` enum('SERVER','DOWNLOAD') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `trigger_type` enum('MANUAL','AUTOMATIC') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('DONE','FAILED') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `size_bytes` bigint unsigned DEFAULT NULL,
  `sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_database_backup_created` (`createdAt`),
  KEY `idx_database_backup_kept` (`destination`,`status`,`deletedAt`),
  KEY `fk_database_backup_creator` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

SET FOREIGN_KEY_CHECKS = 1;
